import heapq
G = {'A': {'B': 1, 'C': 4}, 'B': {'A': 1, 'C': 2, 'D': 5}, 'C': {'A': 4, 'B': 2, 'D': 1}, 'D': {'B': 5, 'C': 1}}
dist = {'A': 0}
pq = [(0, 'A')]
seen = set()
while pq:
    d, u = heapq.heappop(pq)
    if u in seen:
        continue
    seen.add(u)
    for v, w in G[u].items():
        nd = d + w
        if nd < dist.get(v, 10**9):
            dist[v] = nd
            heapq.heappush(pq, (nd, v))
for n in ['B', 'C', 'D']:
    print(dist[n])
